function tr(s) {
  if (s == null) return null;
  const t = s.trim();
  if (!t) return null;
  if (EXACT[t] != null) return s.replace(t, EXACT[t]);
  const pre = t.match(/^(\[T\+\d+\] )(.+)$/);
  if (pre) { const r = tr(pre[2]); return r == null ? null : s.replace(t, pre[1] + r); }
  if (t.endsWith(' ·')) { const r = tr(t.slice(0, -2)); return r == null ? null : s.replace(t, r + ' ·'); }
  for (const [re, f] of PATTERNS) {
    const m = t.match(re);
    if (m) return s.replace(t, f(m));
  }
  return null;
}

