function translateNode(n) {
  if (n.nodeType === 3) {
    if (n.__zh != null && n.data === n.__zh) return;
    const zh = tr(n.data);
    n.__en = n.data;
    if (zh != null && zh !== n.data) { n.__zh = zh; n.data = zh; } else n.__zh = null;
  } else if (n.nodeType === 1) {
    if (n.tagName === 'SCRIPT' || n.tagName === 'STYLE') return;
    if (n.title) {
      if (n.__zhTitle == null || n.title !== n.__zhTitle) {
        const zh = tr(n.title);
        if (zh != null) { n.__enTitle = n.title; n.__zhTitle = zh; n.title = zh; }
      }
    }
    if (n.tagName === 'OPTION') {
      const zh = tr(n.text);
      if (zh != null && n.text !== zh) { n.__en = n.text; n.__zh = zh; n.text = zh; }
      return;
    }
    for (const c of n.childNodes) translateNode(c);
  }
}

function applyBlocks() {
  for (const [sel, zh] of Object.entries(BLOCKS)) {
    const el = document.querySelector(sel);
    if (!el) continue;
    if (!blockEn.has(sel)) blockEn.set(sel, el.innerHTML);
    el.innerHTML = zh;
  }
}

function restore(n) {
  if (n.nodeType === 3) { if (n.__zh != null && n.data === n.__zh) n.data = n.__en; n.__zh = null; }
  else if (n.nodeType === 1) {
    if (n.__zhTitle != null && n.title === n.__zhTitle) n.title = n.__enTitle;
    n.__zhTitle = null;
    if (n.tagName === 'OPTION') { if (n.__zh != null && n.text === n.__zh) n.text = n.__en; n.__zh = null; return; }
    for (const c of n.childNodes) restore(c);
  }
}

const obs = new MutationObserver((muts) => {
  if (lang !== 'zh' || busy) return;
  busy = true;
  for (const m of muts) {
    if (m.type === 'characterData') translateNode(m.target);
    else if (m.type === 'attributes') translateNode(m.target);
    else for (const n of m.addedNodes) translateNode(n);
  }
  busy = false;
});

function updateButtons() {
  for (const b of document.querySelectorAll('.lang-btn')) b.textContent = lang === 'zh' ? 'EN' : '中文';
  document.documentElement.lang = lang === 'zh' ? 'zh-Hant' : 'en';
}

export function setLang(l) {
  lang = l;
  try { localStorage.setItem('lang', l); } catch {}
  busy = true;
  if (l === 'zh') { applyBlocks(); translateNode(document.body); }
  else {
    restore(document.body);
    for (const [sel, en] of blockEn) { const el = document.querySelector(sel); if (el) el.innerHTML = en; }
  }
  busy = false;
  updateButtons();
}

export function initI18n() {
  for (const b of document.querySelectorAll('.lang-btn')) {
    b.addEventListener('click', (e) => { e.stopPropagation(); setLang(lang === 'zh' ? 'en' : 'zh'); });
  }
  obs.observe(document.body, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ['title'] });
  setLang(lang);
}
